"""Pack approved V3 shock / V9 happy sheets without changing source pixels."""
from pathlib import Path
import argparse
from PIL import Image

ROOT = Path(__file__).resolve().parents[1]
ROLES = [('bird', 'baby', 'BabyBird', 14, 2), ('bird', 'adult', 'Bird', 13, 1),
         ('wyvern', 'baby', 'BabyWyvern', 8, 2), ('wyvern', 'adult', 'Wyvern', 8, 1)]


def generate():
    lines = ['#pragma once', '#include <Arduino.h>', '#include <stdint.h>',
             '// Generated by tools/generate_touch_sprite.py. Zero bits are OLED ink.',
             '// V3 poke, V9 authored petting. Do not edit or add heart overlays.',
             'namespace Ui { namespace PetIcons {']
    for species, stage, role, happy_count, shock_count in ROLES:
        for expression, count in [('happy', happy_count), ('shock', shock_count)]:
            path = ROOT / f'assets/pets/{species}/{stage}/{expression}.png'
            image = Image.open(path).convert('RGBA')
            assert image.width % 64 == 0 and image.height % 44 == 0
            assert all(a in (0, 255) and (not a or (r, g, b) == (255, 255, 255))
                       for r, g, b, a in image.get_flattened_data()), path
            tiles = [image.crop((x, y, x+64, y+44)).getchannel('A')
                     for y in range(0, image.height, 44) for x in range(0, image.width, 64)]
            assert len(tiles) >= count and all(t.getbbox() for t in tiles[:count])
            assert all(t.getbbox() is None for t in tiles[count:]), path
            symbol = f'kTouch{role}{expression.title()}'
            lines += [f'// {path.relative_to(ROOT).as_posix()}',
                      f'constexpr uint8_t {symbol}Count = {count};',
                      f'const uint8_t {symbol}[{count}][352] PROGMEM = {{']
            for tile in tiles[:count]:
                data = [sum((0 if tile.getpixel((byte*8+bit, y)) else 1) << (7-bit)
                            for bit in range(8)) for y in range(44) for byte in range(8)]
                assert all(bool(tile.getpixel((x, y))) ==
                           (not (data[y*8+x//8] & (128 >> (x % 8))))
                           for y in range(44) for x in range(64))
                lines += ['    {']
                lines += ['        ' + ', '.join(f'0x{b:02X}' for b in data[i:i+16]) + ','
                          for i in range(0, len(data), 16)]
                lines += ['    },']
            lines += ['};']
    return '\n'.join(lines + ['} } // namespace Ui::PetIcons', ''])


if __name__ == '__main__':
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--check', action='store_true')
    args = parser.parse_args()
    target = ROOT / 'src/ui/TouchSprite.h'
    text = generate()
    if args.check:
        assert target.read_text(encoding='utf-8') == text, 'TouchSprite.h is stale'
        print('PASS: 49 packed touch frames match authored PNG pixels exactly.')
    else:
        target.write_text(text, encoding='utf-8')
        print('Generated 49 original touch frames (17248 bytes).')
